probe_sources.latent_probe.cu:
#include "latent_attention.cuh"
#include <vector>
#include <cstring>

enum latent_path { LATENT_EXPANDED, LATENT_FACTORED, LATENT_FP32_REDUCE };
enum { HEADS = 64, DIM = 256, LATENT = 512, COPIES = 11, WARM = 176 };
static constexpr uint64_t WORKSPACE = 32ull << 20;
struct latent_replay {
    std::vector<void *> allocations;
    cublasHandle_t handle = nullptr;
    cudaEvent_t begin = nullptr, end = nullptr;
    ~latent_replay() {
        if (begin) { cudaEventDestroy(begin); }
        if (end) { cudaEventDestroy(end); }
        if (handle) { cublasDestroy(handle); }
        for (void *p : allocations) { cudaFree(p); }
    }
    bool alloc(void **p, uint64_t bytes, const void *host = nullptr) {
        if (cudaMalloc(p, bytes) != cudaSuccess) { return false; }
        allocations.push_back(*p);
        return !host || cudaMemcpy(*p, host, bytes, cudaMemcpyHostToDevice) == cudaSuccess;
    }
};
extern "C" int bench_latent(const uint16_t *weight, const uint16_t *cache,
        const float *query, float *out, uint16_t *q_stage, uint16_t *p_stage,
        uint16_t *l_stage, uint32_t keys, uint32_t position, uint32_t repeats,
        latent_path path, float *ms) {
    if (!keys || keys > 2048 || position >= keys || !repeats || path > LATENT_FP32_REDUCE) { return -1; }
    latent_replay c;
    __nv_bfloat16 *w = nullptr, *x = nullptr, *expanded = nullptr;
    float *q = nullptr, *y = nullptr;
    uint32_t *pos = nullptr;
    void *scratch = nullptr, *workspace = nullptr;
    const uint64_t wn = HEADS * 2ull * DIM * LATENT, xn = (uint64_t)keys * LATENT;
    const uint64_t qn = HEADS * DIM, low = HEADS * LATENT;
    const auto layout = glmvq_attn_bytes(1, keys, HEADS, DIM);
    if (!c.alloc((void **)&w, wn * COPIES * 2) || !c.alloc((void **)&x, xn * 2, cache) ||
        !c.alloc((void **)&q, qn * sizeof(float), query) || !c.alloc((void **)&y, qn * sizeof(float)) ||
        !c.alloc((void **)&pos, sizeof(uint32_t), &position) ||
        !c.alloc((void **)&expanded, (uint64_t)keys * HEADS * 2 * DIM * 2) ||
        !c.alloc(&scratch, layout.bytes) || !c.alloc(&workspace, WORKSPACE) ||
        cublasCreate(&c.handle) != CUBLAS_STATUS_SUCCESS ||
        cublasSetStream(c.handle, nullptr) != CUBLAS_STATUS_SUCCESS ||
        cublasSetMathMode(c.handle, path == LATENT_FP32_REDUCE ? CUBLAS_MATH_DISALLOW_REDUCED_PRECISION_REDUCTION : CUBLAS_DEFAULT_MATH) != CUBLAS_STATUS_SUCCESS ||
        cublasSetWorkspace(c.handle, workspace, WORKSPACE) != CUBLAS_STATUS_SUCCESS) { return -2; }
    int version = 0;
    if (cublasGetVersion(c.handle, &version) != CUBLAS_STATUS_SUCCESS || version != CUBLAS_VERSION) { return -3; }
    for (unsigned i = 0; i < COPIES; i++) {
        if (cudaMemcpy(w + i * wn, weight, wn * 2, cudaMemcpyHostToDevice) != cudaSuccess) { return -4; }
    }
    auto run = [&](uint32_t i) {
        const __nv_bfloat16 *wi = w + i % COPIES * wn;
        if (path != LATENT_EXPANDED) {
            return glmvq_latent_attn(c.handle, wi, x, q, y, pos,
                1, keys, HEADS, DIM, LATENT, scratch, layout.bytes, nullptr);
        }
        const float alpha = 1.0f, beta = 0.0f;
        const auto status = cublasGemmEx(c.handle, CUBLAS_OP_T, CUBLAS_OP_N,
            HEADS * 2 * DIM, keys, LATENT, &alpha, wi, CUDA_R_16BF, LATENT,
            x, CUDA_R_16BF, LATENT, &beta, expanded, CUDA_R_16BF, HEADS * 2 * DIM,
            CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT_TENSOR_OP);
        if (status != CUBLAS_STATUS_SUCCESS) { return status; }
        return glmvq_attention(c.handle, q, expanded, y, pos, nullptr, 0,
            1, keys, HEADS, DIM, scratch, layout.bytes, nullptr);
    };
    for (unsigned i = 0; i < WARM; i++) { if (run(i) != CUBLAS_STATUS_SUCCESS) { return -5; } }
    if (cudaDeviceSynchronize() != cudaSuccess || cudaEventCreate(&c.begin) != cudaSuccess ||
        cudaEventCreate(&c.end) != cudaSuccess || cudaEventRecord(c.begin) != cudaSuccess) { return -6; }
    for (unsigned i = 0; i < repeats; i++) { if (run(WARM + i) != CUBLAS_STATUS_SUCCESS) { return -7; } }
    if (cudaEventRecord(c.end) != cudaSuccess || cudaEventSynchronize(c.end) != cudaSuccess ||
        cudaEventElapsedTime(ms, c.begin, c.end) != cudaSuccess) { return -8; }
    *ms /= repeats;
    if (cudaMemcpy(out, y, qn * sizeof(float), cudaMemcpyDeviceToHost) != cudaSuccess) { return -9; }
    if (path != LATENT_EXPANDED && q_stage && p_stage && l_stage) {
        const uint8_t *base = (const uint8_t *)scratch;
        if (cudaMemcpy(q_stage, base + layout.kv, low * 2, cudaMemcpyDeviceToHost) != cudaSuccess ||
            cudaMemcpy(l_stage, base + layout.kv + low * 2, low * 2, cudaMemcpyDeviceToHost) != cudaSuccess ||
            cudaMemcpy(p_stage, base + layout.scores, (uint64_t)keys * HEADS * 2, cudaMemcpyDeviceToHost) != cudaSuccess) { return -10; }
    }
    std::vector<uint16_t> restored(xn);
    uint32_t actual_pos = UINT32_MAX;
    if (cudaMemcpy(restored.data(), x, xn * 2, cudaMemcpyDeviceToHost) != cudaSuccess ||
        memcmp(restored.data(), cache, xn * 2) ||
        cudaMemcpy(&actual_pos, pos, sizeof(actual_pos), cudaMemcpyDeviceToHost) != cudaSuccess ||
        actual_pos != position) { return -11; }
    return 0;
}

