#ifndef GLMVQ_LATENT_PROTOTYPE_CUH
#define GLMVQ_LATENT_PROTOTYPE_CUH
#include "cuda/glm_vq_attention.cuh"

/* GLM's no-RoPE latent factorization. BF16 rounding moves from expanded
 * K/V to Q-low and output-low: this is an explicitly approximate candidate. */
static cublasStatus_t glmvq_latent_attn(cublasHandle_t handle,
        const __nv_bfloat16 *weight, const __nv_bfloat16 *cache,
        const float *query, float *output, const uint32_t *positions,
        uint32_t rows, uint32_t keys, uint32_t heads, uint32_t dim,
        uint32_t latent, void *scratch, uint64_t bytes, cudaStream_t stream) {
    if (!handle || !weight || !cache || !query || !output || !positions || !scratch ||
        !rows || !keys || !heads || !dim || !latent ||
        (uint64_t)rows * heads > INT_MAX || keys > INT_MAX ||
        (uint64_t)heads * dim > INT_MAX || latent > INT_MAX) { return CUBLAS_STATUS_INVALID_VALUE; }
    const glmvq_attn_layout l = glmvq_attn_bytes(rows, keys, heads, dim);
    const uint64_t nq = (uint64_t)rows * heads * dim;
    const uint64_t nl = (uint64_t)rows * heads * latent;
    if (bytes < l.bytes || nl * sizeof(__nv_bfloat16) * 2 > l.scores - l.kv) {
        return CUBLAS_STATUS_INVALID_VALUE;
    }
    auto *base = (uint8_t *)scratch;
    auto *q = (__nv_bfloat16 *)(base + l.q);
    auto *qlow = (__nv_bfloat16 *)(base + l.kv), *low = qlow + nl;
    auto *scores = (__nv_bfloat16 *)(base + l.scores);
    auto *y = (__nv_bfloat16 *)(base + l.output);
    const float alpha = 1.0f, beta = 0.0f;
    const long long wstride = (long long)2 * dim * latent;
    glmvq_convert<<<(nq + GLMVQ_THREADS - 1) / GLMVQ_THREADS, GLMVQ_THREADS, 0, stream>>>(query, q, nq);
    if (cudaGetLastError() != cudaSuccess) { return CUBLAS_STATUS_EXECUTION_FAILED; }
    cublasStatus_t status = cublasGemmStridedBatchedEx(handle, CUBLAS_OP_N, CUBLAS_OP_N,
        latent, rows, dim, &alpha, weight, CUDA_R_16BF, latent, wstride,
        q, CUDA_R_16BF, heads * dim, dim, &beta, qlow, CUDA_R_16BF,
        latent, (uint64_t)rows * latent, heads, CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT_TENSOR_OP);
    if (status != CUBLAS_STATUS_SUCCESS) { return status; }
    // All heads share C. Fold heads into N instead of replicating C or using zero strides.
    status = cublasGemmEx(handle, CUBLAS_OP_T, CUBLAS_OP_N,
        keys, rows * heads, latent, &alpha, cache, CUDA_R_16BF, latent,
        qlow, CUDA_R_16BF, latent, &beta, scores, CUDA_R_16BF, keys,
        CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT_TENSOR_OP);
    if (status != CUBLAS_STATUS_SUCCESS) { return status; }
    glmvq_attn_softmax<<<dim3(rows, heads), GLMVQ_THREADS, 0, stream>>>(
        scores, nullptr, positions, rows, keys, 1.0f / sqrtf((float)dim));
    if (cudaGetLastError() != cudaSuccess) { return CUBLAS_STATUS_EXECUTION_FAILED; }
    status = cublasGemmEx(handle, CUBLAS_OP_N, CUBLAS_OP_N,
        latent, rows * heads, keys, &alpha, cache, CUDA_R_16BF, latent,
        scores, CUDA_R_16BF, keys, &beta, low, CUDA_R_16BF, latent,
        CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT_TENSOR_OP);
    if (status != CUBLAS_STATUS_SUCCESS) { return status; }
    status = cublasGemmStridedBatchedEx(handle, CUBLAS_OP_T, CUBLAS_OP_N,
        dim, rows, latent, &alpha, weight + (uint64_t)dim * latent,
        CUDA_R_16BF, latent, wstride, low, CUDA_R_16BF, latent,
        (uint64_t)rows * latent, &beta, y, CUDA_R_16BF, dim,
        (uint64_t)rows * dim, heads, CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT_TENSOR_OP);
    if (status != CUBLAS_STATUS_SUCCESS) { return status; }
    glmvq_attn_output<<<(nq + GLMVQ_THREADS - 1) / GLMVQ_THREADS, GLMVQ_THREADS, 0, stream>>>(
        output, y, rows, heads, dim, nq);
    return cudaGetLastError() == cudaSuccess ? CUBLAS_STATUS_SUCCESS : CUBLAS_STATUS_EXECUTION_FAILED;
}
#endif

probe_sources.kv_projection_probe.cu:
// Replay the current KV_B GEMM without loading the model or changing inference.
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <cuda_profiler_api.h>
#include <cublas_v2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <vector>

#define CUDA_TRY(x) do { cudaError_t s=(x); if(s!=cudaSuccess) { \
 fprintf(stderr,"%s: %s\n",#x,cudaGetErrorString(s));return 1;} } while(0)
#define BLAS_TRY(x) do { cublasStatus_t s=(x); if(s!=CUBLAS_STATUS_SUCCESS) { \
 fprintf(stderr,"%s: cuBLAS %d\n",#x,(int)s);return 2;} } while(0)

enum { OUT = 32768, INNER = 512, KEYS = 1985, LAYERS = 11, WARM = 16, REPEAT = 64 };
static constexpr size_t WORKSPACE = 32ull * 1024 * 1024;

static cublasStatus_t project(cublasHandle_t handle, const __nv_bfloat16 *w,
        const __nv_bfloat16 *x, __nv_bfloat16 *y) {
    const float alpha=1.0f,beta=0.0f;
    return cublasGemmEx(handle,CUBLAS_OP_T,CUBLAS_OP_N,OUT,KEYS,INNER,
        &alpha,w,CUDA_R_16BF,INNER,x,CUDA_R_16BF,INNER,&beta,y,CUDA_R_16BF,OUT,
        CUBLAS_COMPUTE_32F,CUBLAS_GEMM_DEFAULT_TENSOR_OP);
}

int main(int argc,char **argv) {
    if(argc<2 || argc>3) { return 3; }
    const bool profile=argc==3 && !strcmp(argv[2],"--profile");
    const size_t wn=(size_t)OUT*INNER, xn=(size_t)KEYS*INNER, yn=(size_t)KEYS*OUT;
    std::vector<uint16_t> weight(wn), input(xn*LAYERS);
    FILE *f=fopen(argv[1],"rb");
    if(!f || fread(weight.data(),2,wn,f)!=wn || fgetc(f)!=EOF) { return 4; }
    fclose(f);
    for(size_t i=0;i<input.size();i++) {
        uint32_t n=(uint32_t)i ^ 0x5353u;
        n^=n>>16;n*=0x7feb352du;n^=n>>15;n*=0x846ca68bu;n^=n>>16;
        const float v=((int)(n%255)-127)/128.0f;
        uint32_t bits;memcpy(&bits,&v,4);input[i]=bits>>16;
    }
    __nv_bfloat16 *w=nullptr,*x=nullptr,*y=nullptr;void *work=nullptr;
    CUDA_TRY(cudaMalloc(&w,wn*LAYERS*2));
    CUDA_TRY(cudaMalloc(&x,xn*LAYERS*2));
    CUDA_TRY(cudaMalloc(&y,yn*2));
    CUDA_TRY(cudaMalloc(&work,WORKSPACE));
    for(int i=0;i<LAYERS;i++) { CUDA_TRY(cudaMemcpy(w+i*wn,weight.data(),wn*2,cudaMemcpyHostToDevice)); }
    CUDA_TRY(cudaMemcpy(x,input.data(),input.size()*2,cudaMemcpyHostToDevice));
    cublasHandle_t handle=nullptr;
    BLAS_TRY(cublasCreate(&handle));
    BLAS_TRY(cublasSetMathMode(handle,CUBLAS_DEFAULT_MATH));
    BLAS_TRY(cublasSetWorkspace(handle,work,WORKSPACE));
    for(int r=0;r<WARM;r++) { for(int i=0;i<LAYERS;i++) { BLAS_TRY(project(handle,w+i*wn,x+i*xn,y)); } }
    CUDA_TRY(cudaDeviceSynchronize());
    cudaEvent_t start,stop;CUDA_TRY(cudaEventCreate(&start));CUDA_TRY(cudaEventCreate(&stop));
    if(profile) { CUDA_TRY(cudaProfilerStart()); }
    CUDA_TRY(cudaEventRecord(start));
    const int rounds=profile?1:REPEAT, layers=profile?1:LAYERS;
    for(int r=0;r<rounds;r++) { for(int i=0;i<layers;i++) { BLAS_TRY(project(handle,w+i*wn,x+i*xn,y)); } }
    CUDA_TRY(cudaEventRecord(stop));CUDA_TRY(cudaEventSynchronize(stop));
    if(profile) { CUDA_TRY(cudaProfilerStop()); }
    float ms=0;CUDA_TRY(cudaEventElapsedTime(&ms,start,stop));
    uint16_t bits;CUDA_TRY(cudaMemcpy(&bits,y+yn-1,2,cudaMemcpyDeviceToHost));
    uint32_t fbits=(uint32_t)bits<<16;float last;memcpy(&last,&fbits,4);
    if(!isfinite(last)) { return 5; }
    int runtime=0,driver=0,blas=0;
    CUDA_TRY(cudaRuntimeGetVersion(&runtime));CUDA_TRY(cudaDriverGetVersion(&driver));BLAS_TRY(cublasGetVersion(handle,&blas));
    printf("{\"m\":%d,\"n\":%d,\"k\":%d,\"layers\":%d,\"rounds\":%d,\"ms_per_call\":%.9g,\"flops_per_call\":%llu,\"weight_set_bytes\":%llu,\"last\":%.9g,\"runtime\":%d,\"driver\":%d,\"cublas\":%d}\n",
        OUT,KEYS,INNER,layers,rounds,ms/(rounds*layers),(unsigned long long)(2ull*OUT*KEYS*INNER),(unsigned long long)(wn*LAYERS*2),last,runtime,driver,blas);
    BLAS_TRY(cublasDestroy(handle));CUDA_TRY(cudaEventDestroy(start));CUDA_TRY(cudaEventDestroy(stop));
    CUDA_TRY(cudaFree(work));CUDA_TRY(cudaFree(y));CUDA_TRY(cudaFree(x));CUDA_TRY(cudaFree(w));
    return 0;
}
